function validate([s, c]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 100000) return 's needs 1 to 100000 characters.';
  if (!/^[a-z]+$/.test(s)) return 's uses only lowercase English letters.';
  if (typeof c !== 'string' || !/^[a-z]$/.test(c)) return 'c is one lowercase English letter.';
  return null;
}

