function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const alphabet = ['a', 'ab', 'abc', 'xyz', 'abcdefghijklmnopqrstuvwxyz'][int(0, 4)];
  const length = size === 'large' ? int(9000, 10000) : int(1, 12);
  let s = '';
  for (let i = 0; i < length; i++) s += alphabet[int(0, alphabet.length - 1)];
  const c = rand() < 0.8 ? alphabet[int(0, alphabet.length - 1)] : 'abcdefghijklmnopqrstuvwxyz'[int(0, 25)];
  return [s, c];
}
